<?php
declare(strict_types=1);
function productionBrandCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner):void {
    $source=null;$jobs=[];$builder=null;$brands=null;$c=null;$ctx=null;$selected=null;
    $tests['normal release opt-in creates separate production jobs from published branding without test suffixes or history resets']=function()use($app,$config,$owner,&$source,&$jobs,&$builder,&$brands,&$c,&$ctx,&$selected):void {
        $source=$app->db->one('SELECT * FROM brand_main_sources ORDER BY version_code DESC LIMIT 1');check($source!==null);$token=str_repeat('4',64);
        $c=new ControlCenter\Config($config->root,array_replace($config->values,['brand_release'=>['default_channel'=>'production'],'brand_main_updates'=>['production_enabled'=>true,'testing_enabled'=>false],'brand_builder'=>['enabled'=>true,'publication_enabled'=>true,'automatic_production_publication'=>true,'channels'=>['production'],'sources'=>[$source['app_version']=>$source['source_sha']]],'brand_dispatch'=>['enabled'=>true,'token_sha256'=>hash('sha256',$token)],'brand_downloads'=>['enabled'=>false]]));$s=new ControlCenter\Secrets($c);$a=new ControlCenter\BrandArtifacts($app->db,$s,$c);$brands=new ControlCenter\AppBrands($app->db,$app->management,$app->auth,$a,$c);$builder=new ControlCenter\BrandBuilder($app->db,$c,$brands,$a,$s,$app->auth);
        $before=$app->db->all('SELECT * FROM app_brands ORDER BY id');$testing=$app->db->all("SELECT * FROM app_brand_artifacts WHERE channel='testing' ORDER BY id");$trials=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');
        $input=['source_sha'=>$source['source_sha'],'workflow_ref'=>$source['workflow_ref'],'app_version'=>$source['app_version'],'version_code'=>(int)$source['version_code'],'channel'=>'production'];
        // A source registered by testing is NOT production publication authority.
        $reject=new ControlCenter\BrandMainUpdates($app->db,$c,$a,$app->auth,static function(){throw new ControlCenter\Problem(409,'Customer release not published');});
        problem(409,fn()=> $reject->fanout($input));
        $verified=0;$updates=new ControlCenter\BrandMainUpdates($app->db,$c,$a,$app->auth,static function($document)use($input,&$verified){same($input,$document);$verified++;});
        $result=$updates->fanout($input);check($result['queued']>0);same($before,$app->db->all('SELECT * FROM app_brands ORDER BY id'));same($testing,$app->db->all("SELECT * FROM app_brand_artifacts WHERE channel='testing' ORDER BY id"));same($trials,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same(['complete'=>true,'queued'=>0],$updates->fanout($input));same(2,$verified);
        $jobs=$app->db->all("SELECT * FROM app_brand_builds WHERE build_channel='production' AND source_sha=?",[$source['source_sha']]);check(count($jobs)>0);$selected=$jobs[0];$ctx=$builder->claim(['build_id'=>$selected['id'],'source_sha'=>$source['source_sha'],'channel'=>'production','runner_run_id'=>'7777']);check(!str_ends_with($ctx['expected']['package_name'],'.test'));check(!str_contains($ctx['expected']['asset_name'],'-test'));check(!str_contains($ctx['expected']['version_name'],'-test'));same('production',$ctx['expected']['channel']);
        $view=$brands->get($owner,['tenant_id'=>$app->db->one('SELECT tenant_id FROM app_brands WHERE id=?',[$selected['brand_id']])['tenant_id']]);same('production',$view['release_channel']);check(array_reduce($view['builds'],static fn($ok,$j)=>$ok&&!str_contains($j['app_version'],'test'),true));
    };
    $tests['production pickup requires explicit publication opt-in and uses its immutable main tag']=function()use($app,$owner,&$source,&$builder,&$brands,&$c,&$jobs):void {
        $token=str_repeat('4',64);$hint=$builder->poll(['channel'=>'production','source_sha'=>$source['source_sha'],'mode'=>'publish'],'Bearer '.$token);same('production',$hint['channel']);same($source['workflow_ref'],$hint['workflow_ref']);
        $off=new ControlCenter\Config($c->root,array_replace($c->values,['brand_builder'=>array_replace($c->values['brand_builder'],['automatic_production_publication'=>false])]));$s=new ControlCenter\Secrets($off);$blocked=new ControlCenter\BrandBuilder($app->db,$off,$brands,new ControlCenter\BrandArtifacts($app->db,$s,$off),$s,$app->auth);problem(403,fn()=> $blocked->poll(['channel'=>'production','source_sha'=>$source['source_sha'],'mode'=>'publish'],'Bearer '.$token));
        problem(403,fn()=> $builder->claim(['build_id'=>$jobs[0]['id'],'channel'=>'testing','source_sha'=>$source['source_sha']]));
    };
    $tests['verified normal release preserves testing artifact and all future branding identity checks']=function()use($app,$owner,&$builder,&$brands,&$c,&$ctx,&$selected):void {
        $s=new ControlCenter\Secrets($c);$artifacts=new ControlCenter\BrandArtifacts($app->db,$s,$c);$test=$artifacts->approved($selected['brand_id'],'testing');$r=$ctx['expected'];unset($r['release_tag'],$r['asset_name']);$r+=['source_sha'=>$ctx['source_sha'],'apk_sha256'=>str_repeat('6',64),'apk_size_bytes'=>150000000,'provenance_sha256'=>str_repeat('7',64)];$lease=['build_id'=>$ctx['build_id'],'lease_token'=>$ctx['lease_token']];$builder->prepared($lease+['receipt'=>$r]);$builder->authorize($lease+['confirmed_publication'=>true]);same('published',$builder->finish($lease+['receipt'=>$r])['state']);same($test,$artifacts->approved($selected['brand_id'],'testing'));$normal=$artifacts->approved($selected['brand_id'],'production');same($ctx['expected']['package_name'],$normal['package_name']);same($normal['package_name'],$artifacts->enrollmentPackage($normal['package_name']));
        $tenant=$app->db->one('SELECT tenant_id FROM app_brands WHERE id=?',[$selected['brand_id']])['tenant_id'];$view=$brands->get($owner,['tenant_id'=>$tenant]);same(1,count($view['artifacts']));same('production',$view['artifacts'][0]['channel']);
    };
    $tests['main update catches a concurrent published rebrand and can never roll its name or artwork backwards']=function()use($app,$owner,&$builder,&$brands,&$c,&$selected,&$source):void {
        $current=$app->db->one('SELECT * FROM app_brands WHERE id=?',[$selected['brand_id']]);$before=$app->db->one('SELECT manifest FROM app_brand_builds WHERE id=?',[$selected['id']]);$old=json_decode($before['manifest'],true);
        $saved=$brands->save($owner,['tenant_id'=>$current['tenant_id'],'expected_version'=>(int)$current['version'],'name'=>'TEST Production Rebrand','loading_asset'=>$current['loading_asset'],'logo_asset'=>$current['logo_asset'],'icon_asset'=>$current['icon_asset']]);$rebrand=$brands->requestBuild($owner,['tenant_id'=>$current['tenant_id'],'expected_version'=>$saved['version']]);
        $next=['source_sha'=>str_repeat('7',40),'workflow_ref'=>'brand-source-2.0.117-'.str_repeat('7',40),'app_version'=>'2.0.117','version_code'=>433,'channel'=>'production'];$s=new ControlCenter\Secrets($c);$a=new ControlCenter\BrandArtifacts($app->db,$s,$c);$updates=new ControlCenter\BrandMainUpdates($app->db,$c,$a,$app->auth,static function($input)use($next){same($next,$input);});$updates->fanout($next);
        $stale=$app->db->one("SELECT * FROM app_brand_builds WHERE brand_id=? AND app_version='2.0.117' AND build_channel='production' AND brand_version=?",[$current['id'],$old['brand_version']]);check($stale!==null);
        $publish=function(array $context)use($builder):void {$r=$context['expected'];unset($r['release_tag'],$r['asset_name']);$r+=['source_sha'=>$context['source_sha'],'apk_sha256'=>str_repeat('8',64),'apk_size_bytes'=>150000000,'provenance_sha256'=>str_repeat('9',64)];$lease=['build_id'=>$context['build_id'],'lease_token'=>$context['lease_token']];$builder->prepared($lease+['receipt'=>$r]);$builder->authorize($lease+['confirmed_publication'=>true]);$builder->finish($lease+['receipt'=>$r]);};
        $new=$builder->claim(['build_id'=>$rebrand['id'],'channel'=>'production','source_sha'=>$source['source_sha'],'runner_run_id'=>'8888']);$publish($new);
        same('cancelled',$app->db->one('SELECT state FROM app_brand_builds WHERE id=?',[$stale['id']])['state']);
        $caught=$app->db->one("SELECT * FROM app_brand_builds WHERE brand_id=? AND app_version='2.0.117' AND build_channel='production' AND brand_version=?",[$current['id'],$saved['version']]);check($caught!==null);$manifest=json_decode($caught['manifest'],true);same('TEST Production Rebrand',$manifest['app_name']);same($current['package_name'],$manifest['package_name']);same($old['assets'],$manifest['assets']);
        $latest=$builder->claim(['build_id'=>$caught['id'],'channel'=>'production','source_sha'=>$next['source_sha'],'runner_run_id'=>'9999']);$publish($latest);$live=$a->approved($current['id'],'production');same($latest['expected']['package_name'],$live['package_name']);same($latest['expected']['version_name'],$live['version_name']);
    };
}
